package io.ledgerflow.account.adapter.out.persistence;

import jakarta.persistence.*;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;

@Entity
@Table(name = "accounts")
class AccountEntity {

    @Id
    private UUID id;

    @Column(nullable = false)
    private String name;

    @OneToMany(mappedBy = "account", fetch = FetchType.EAGER)
    private List<WalletEntity> wallets = new ArrayList<>();

    protected AccountEntity() { }   // Hibernate needs this

    UUID id()               { return id; }
    String name()           { return name; }
    List<WalletEntity> wallets(){ return wallets; }
}

package io.ledgerflow.account.adapter.out.persistence;

import jakarta.persistence.*;
import java.util.UUID;

@Entity
@Table(name = "wallets")
class WalletEntity {

    @Id
    private UUID id;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "account_id", nullable = false)
    private AccountEntity account;

    @Column(nullable = false)
    private String label;

    protected WalletEntity() { }

    UUID id()      { return id; }
    String label() { return label; }
}

package io.ledgerflow.account.adapter.out.persistence;

import org.springframework.data.jpa.repository.JpaRepository;
import java.util.UUID;

interface JpaAccountRepository extends JpaRepository<AccountEntity, UUID> { }

package io.ledgerflow.account.adapter.out.persistence;

import io.ledgerflow.account.application.AccountRepository;
import io.ledgerflow.account.domain.model.Wallet;
import io.ledgerflow.account.domain.model.Account;
import org.springframework.stereotype.Component;

import java.util.List;
import java.util.Optional;
import java.util.UUID;

@Component
class AccountRepositoryAdapter implements AccountRepository {

    private final JpaAccountRepository jpa;

    AccountRepositoryAdapter(JpaAccountRepository jpa) { this.jpa = jpa; }

    @Override
    public List<Account> findAll() {
        return jpa.findAll().stream().map(AccountRepositoryAdapter::toDomain).toList();
    }

    @Override
    public Optional<Account> findById(UUID id) {
        return jpa.findById(id).map(AccountRepositoryAdapter::toDomain);
    }

    private static Account toDomain(AccountEntity e) {
        return new Account(e.id(), e.name(),
                e.wallets().stream().map(s -> new Wallet(s.id(), s.label())).toList());
    }
}

package io.ledgerflow.account.application;

import io.ledgerflow.account.domain.model.Account;

import java.util.List;
import java.util.Optional;
import java.util.UUID;

public interface AccountRepository {
    List<Account> findAll();
    Optional<Account> findById(UUID id);
}

package io.ledgerflow.account.adapter.in.web;

import io.ledgerflow.account.application.AccountRepository;
import io.ledgerflow.account.domain.model.Account;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.util.List;
import java.util.UUID;

@RestController
@RequestMapping("/api/v1/accounts")
public class AccountController {

    private final AccountRepository accounts;

    AccountController(AccountRepository accounts) { this.accounts = accounts; }

    @GetMapping
    public List<Account> all() {
        return accounts.findAll();
    }

    @GetMapping("/{id}")
    public ResponseEntity<Account> byId(@PathVariable UUID id) {
        return accounts.findById(id)
                     .map(ResponseEntity::ok)
                     .orElseGet(() -> ResponseEntity.notFound().build());
    }
}

package io.ledgerflow.account;

import io.ledgerflow.account.application.AccountRepository;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.testcontainers.service.connection.ServiceConnection;
import org.testcontainers.postgresql.PostgreSQLContainer;
import org.testcontainers.junit.jupiter.Container;
import org.testcontainers.junit.jupiter.Testcontainers;

import java.util.UUID;

import static org.assertj.core.api.Assertions.assertThat;

@Testcontainers
@SpringBootTest
class AccountRepositoryIT {

    @Container
    @ServiceConnection
    static PostgreSQLContainer postgres = new PostgreSQLContainer("postgres:17");

    @Autowired AccountRepository accounts;

    @Test
    void seededAccountIsReadable() {
        var demo = UUID.fromString("11111111-1111-1111-1111-111111111111");

        var account = accounts.findById(demo).orElseThrow();

        assertThat(account.name()).isEqualTo("Demo Arena");
        assertThat(account.wallets()).hasSize(20);
        assertThat(account.hasWallet("A-12")).isTrue();
    }
}
